using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public record CredentialIssue(Guid MembershipId,Guid TemplateVersionId,DateOnly ExpiryDate,Guid? PreviousId=null,string Reason="",Guid? EventId=null,Guid? ProjectId=null);
public record StudioSelection(Guid? UnitId=null,Guid? CategoryId=null,string? Designation=null,string Status="Active",DateOnly? JoinedFrom=null,DateOnly? JoinedTo=null,DateOnly? ExpiresBefore=null,Guid[]? MembershipIds=null);
public record StudioBatch(Guid TemplateVersionId,StudioSelection Selection,DateOnly ExpiryDate,string Key,string Reason="",Guid? EventId=null,Guid? ProjectId=null);
public record StudioReview(string Decision,string Note="");
public record PrintLayout(string Format="zip-pdf",string Sides="Both",double SheetWidthMm=210,double SheetHeightMm=297,int Columns=2,int Rows=5,double MarginMm=10,double GapMm=3,bool CropMarks=true,bool Duplex=true,double OffsetX=0,double OffsetY=0,bool Bleed=false);
public class StudioService(AppDb db,Access access,IDataProtectionProvider protection,IConfiguration config){
 public static readonly string[] Permissions=["studio.read","studio.design","studio.publish","studio.issue","studio.approve","studio.bulk","studio.settings","service.read","service.manage","service.approve","service.coordinate","service.verify","intelligence.read","reports.export","reports.schedule","assistant.use","branding.manage"];
 public static string[] TemplatePermissions(string name)=>name.Contains("President")||name.Contains("Secretary")||name.Contains("Governor")||name.Contains("Coordinator")||name.Contains("Manager")?["studio.read","studio.design","studio.issue","studio.approve","service.read","service.manage","service.approve","service.coordinate","service.verify","intelligence.read","reports.export","assistant.use"]:name.Contains("Treasurer")?["studio.read","service.read","intelligence.read","assistant.use"]:[];
 public async Task<StudioPolicy> Policy(Guid tenant){await access.Member(tenant);var p=await db.Set<StudioPolicy>().SingleOrDefaultAsync(p=>p.TenantId==tenant);if(p!=null)return p;p=new(){TenantId=tenant};db.Add(p);await db.SaveChangesAsync();return p;}
 public IQueryable<T> Scoped<T>(Guid tenant,string permission="studio.read",Guid? workspace=null) where T:StudioRecord{var permitted=access.InWorkspace(access.Visible(tenant,permission),tenant,workspace);var units=permitted.Select(u=>u.Id);if(typeof(T)==typeof(DesignTemplate)&&permission=="studio.read"){var shared=db.Set<DesignTemplate>().Where(t=>t.TenantId==tenant&&((t.UnitId==null&&t.PublishedVersion>0&&t.Status!="Archived"&&permitted.Any())||(t.UnitId!=null&&(units.Contains(t.UnitId.Value)||t.PublishedVersion>0&&t.Status!="Archived"&&permitted.Any(u=>AppDb.UnitWithin(tenant,u.Id,t.UnitId.Value))))));var global=db.Assignments.Where(a=>a.TenantId==tenant&&a.UserId==access.UserId&&a.UnitId==null&&a.RevokedAt==null&&a.StartsAt<=DateTimeOffset.UtcNow&&(a.EndsAt==null||a.EndsAt>DateTimeOffset.UtcNow)&&db.GovernanceRoles.Any(r=>r.Id==a.RoleId&&r.Permissions.Contains(permission))&&(a.MembershipId==null||db.Memberships.Any(m=>m.Id==a.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow))));return (IQueryable<T>)(object)db.Set<DesignTemplate>().Where(t=>t.TenantId==tenant&&(global.Any()||shared.Select(s=>s.Id).Contains(t.Id)));}return db.Set<T>().Where(x=>x.TenantId==tenant&&(x.UnitId==null?db.Assignments.Any(a=>a.TenantId==tenant&&a.UserId==access.UserId&&a.UnitId==null&&a.RevokedAt==null&&a.StartsAt<=DateTimeOffset.UtcNow&&(a.EndsAt==null||a.EndsAt>DateTimeOffset.UtcNow)&&db.GovernanceRoles.Any(r=>r.Id==a.RoleId&&r.Permissions.Contains(permission))&&(a.MembershipId==null||db.Memberships.Any(m=>m.Id==a.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow)))):units.Contains(x.UnitId.Value)));}
 public async Task<bool> Own(Guid tenant,Guid membership)=>await db.Memberships.AnyAsync(m=>m.TenantId==tenant&&m.Id==membership&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==access.UserId));
 public async Task Require(Guid tenant,string permission,Guid? unit=null){await access.Require(tenant,permission,unit);}
 public IQueryable<Membership> Select(Guid tenant,StudioSelection r,string permission="studio.issue"){var units=access.InWorkspace(access.Visible(tenant,permission),tenant,r.UnitId).Select(u=>u.Id);var q=db.Memberships.Where(m=>m.TenantId==tenant&&units.Contains(m.ChapterId));if(r.MembershipIds!=null){if(r.MembershipIds.Length>100000)throw new DomainException("Select at most 100,000 memberships");q=q.Where(m=>r.MembershipIds.Contains(m.Id));}if(r.CategoryId!=null)q=q.Where(m=>m.CategoryId==r.CategoryId);if(!string.IsNullOrEmpty(r.Status))q=q.Where(m=>m.Status==r.Status);if(r.JoinedFrom!=null){var from=r.JoinedFrom.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);q=q.Where(m=>m.JoinedAt>=from);}if(r.JoinedTo!=null){var to=r.JoinedTo.Value.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);q=q.Where(m=>m.JoinedAt<to);}if(r.ExpiresBefore!=null){var end=r.ExpiresBefore.Value.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);q=q.Where(m=>m.EndsAt!=null&&m.EndsAt<end);}if(!string.IsNullOrEmpty(r.Designation)){var now=DateTimeOffset.UtcNow;q=q.Where(m=>db.OfficerAppointments.Any(o=>o.TenantId==tenant&&o.MembershipId==m.Id&&o.Status=="Approved"&&o.StartsAt<=now&&o.EndsAt>now&&db.OfficerPositions.Any(p=>p.Id==o.PositionId&&p.Name==r.Designation)));}return q;}
 public async Task<DesignVersion> Version(Guid tenant,Guid id,Guid chapter){var v=await db.Set<DesignVersion>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.Id==id)??throw new DomainException("Choose a published template version");var t=await db.Set<DesignTemplate>().SingleAsync(t=>t.Id==v.TemplateId&&t.TenantId==tenant);if(t.Status=="Archived")throw new DomainException("This template is archived");if(v.UnitId!=null&&!await access.InWorkspace(db.Units.Where(u=>u.TenantId==tenant),tenant,v.UnitId).AnyAsync(u=>u.Id==chapter))throw new DomainException("Template is not assigned to this organization");return v;}
 public async Task ValidateAssets(Guid tenant,DocumentDesign design){foreach(var id in design.Front.Concat(design.Back).Where(e=>e.AssetId!=null).Select(e=>e.AssetId!.Value).Distinct()){var asset=await db.Set<StudioAsset>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Kind=="Image")??throw new DomainException("A design asset is missing or outside this society");await access.Require(tenant,"studio.design",asset.UnitId);}}
 public async Task<CredentialSnapshot> Snapshot(Guid tenant,Membership m,DesignVersion version,DateOnly issue,DateOnly expiry,string serial,string token,string reason,Guid? eventId,Guid? projectId){
  var now=DateTimeOffset.UtcNow;if(m.Status!="Active"||m.EffectiveFrom>now||m.EndsAt<=now)throw new DomainException("Membership is not currently active");if(expiry<issue||expiry>issue.AddYears(10)||(m.EndsAt!=null&&expiry>DateOnly.FromDateTime(m.EndsAt.Value.UtcDateTime)))throw new DomainException("Expiry must follow issuance and stay within the membership term and ten years");var template=await db.Set<DesignTemplate>().SingleAsync(t=>t.Id==version.TemplateId&&t.TenantId==tenant);if(template.CategoryId!=null&&template.CategoryId!=m.CategoryId)throw new DomainException("Membership category does not match this template");
  var roles=await (from o in db.OfficerAppointments join p in db.OfficerPositions on o.PositionId equals p.Id where o.TenantId==tenant&&o.MembershipId==m.Id&&o.Status=="Approved"&&o.StartsAt<=now&&o.EndsAt>now select p.Name).Distinct().ToArrayAsync();if(template.Designation!=""&&!roles.Contains(template.Designation))throw new DomainException("Current designation does not match this template");
  var person=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);var chapter=await db.Units.SingleAsync(u=>u.TenantId==tenant&&u.Id==m.ChapterId);var society=await db.Tenants.SingleAsync(t=>t.Id==tenant);var category=await db.MembershipCategories.SingleAsync(c=>c.TenantId==tenant&&c.Id==m.CategoryId);var region="";var parent=chapter.ParentId;var visited=new HashSet<Guid>();while(parent!=null&&visited.Add(parent.Value)){var ancestor=await db.Units.SingleAsync(u=>u.TenantId==tenant&&u.Id==parent);if(await db.Levels.AnyAsync(l=>l.Id==ancestor.LevelId&&l.Kind=="Region")){region=ancestor.Name;break;}parent=ancestor.ParentId;}
  var eventName="";if(eventId!=null){var ev=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==eventId)??throw new DomainException("Event not found");if(!await db.Set<EventAttendance>().AnyAsync(a=>a.TenantId==tenant&&a.EventId==eventId&&!a.Voided&&db.Set<EventRegistration>().Any(r=>r.Id==a.RegistrationId&&r.MembershipId==m.Id)))throw new DomainException("Participation certificate requires actual recorded event attendance");eventName=ev.Title;}
  var projectName="";if(projectId!=null){var project=await db.Set<ServiceProject>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==projectId&&p.Status=="Approved"||p.TenantId==tenant&&p.Id==projectId&&p.Status=="Completed")??throw new DomainException("Choose an approved service project");if(!await db.Set<VolunteerAssignment>().AnyAsync(v=>v.TenantId==tenant&&v.ProjectId==projectId&&v.MembershipId==m.Id&&v.Status=="Approved"))throw new DomainException("Project certificate requires an approved volunteer assignment");projectName=project.Name;}
  var hours=await db.Set<VolunteerAttendance>().Where(v=>v.TenantId==tenant&&v.MembershipId==m.Id&&v.Status=="Verified"&&(projectId==null||db.Set<VolunteerShift>().Any(s=>s.Id==v.ShiftId&&s.ProjectId==projectId))).SumAsync(v=>v.Hours);
  var fields=new Dictionary<string,string>{{"member.full_name",person.FullName},{"member.member_id",m.Number},{"member.membership_category",category.Name},{"member.joining_date",m.JoinedAt.ToString("yyyy-MM-dd")},{"member.expiry_date",m.EndsAt?.ToString("yyyy-MM-dd")??""},{"member.current_role",string.Join(", ",roles)},{"chapter.name",chapter.Name},{"region.name",region},{"society.name",society.Name},{"card.issue_date",issue.ToString("yyyy-MM-dd")},{"card.expiry_date",expiry.ToString("yyyy-MM-dd")},{"card.serial_number",serial},{"card.qr_code",(config["PublicUrl"]??throw new DomainException("Configure PublicUrl for QR verification")).TrimEnd('/')+"/verify/credential/"+token},{"event.name",eventName},{"project.name",projectName},{"certificate.title",template.Name},{"certificate.reason",reason},{"volunteer.verified_hours",hours.ToString("0.##",System.Globalization.CultureInfo.InvariantCulture)}};
  var images=new Dictionary<string,Guid>();var photo=await db.MemberDocuments.Where(d=>d.TenantId==tenant&&d.MembershipId==m.Id&&d.Kind=="Photo").OrderByDescending(d=>d.CreatedAt).Select(d=>(Guid?)d.Id).FirstOrDefaultAsync();if(photo!=null)images["member.photo"]=photo.Value;
  var profile=MembershipService.Json(society.Profile);var details=MembershipService.Json(chapter.Details);foreach(var key in new[]{"society.logo","chapter.logo"}){var url=(key=="society.logo"?profile:details)["logoUrl"]?.GetValue<string>();if(Uri.TryCreate(url??"",UriKind.RelativeOrAbsolute,out _)&&Guid.TryParse((url??"").Split('/').Last(),out var id)&&await db.Assets.AnyAsync(a=>a.TenantId==tenant&&a.Id==id))images[key]=id;}var brand=await db.Set<TenantBrand>().SingleOrDefaultAsync(b=>b.TenantId==tenant);if(brand?.LogoId!=null)images["society.logo"]=brand.LogoId.Value;
  var design=DesignSchema.Parse(version.Design);foreach(var element in design.Front.Concat(design.Back).Where(e=>e.Required)){if(element.Type=="Image"){if(element.AssetId==null&&!images.ContainsKey(element.Binding))throw new DomainException("Required image missing: "+element.Binding);}else{var bound=element.Binding!=""?new[]{element.Binding}:System.Text.RegularExpressions.Regex.Matches(element.Text,@"\{\{([^{}]+)\}\}").Select(x=>x.Groups[1].Value.Trim()).ToArray();foreach(var field in bound)if(string.IsNullOrWhiteSpace(fields.GetValueOrDefault(field)))throw new DomainException("Required field missing: "+field);}}
  return new(design,fields,images);
 }
 public async Task<Credential> Request(Guid tenant,CredentialIssue r,Guid? job=null,Guid? approver=null){if(!await db.Tenants.AnyAsync(t=>t.Id==tenant&&t.Status=="Active"))throw new DomainException("Activate the society before official issuance");var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==r.MembershipId)??throw new AccessDeniedException();await Require(tenant,"studio.issue",m.ChapterId);var v=await Version(tenant,r.TemplateVersionId,m.ChapterId);var template=await db.Set<DesignTemplate>().SingleAsync(t=>t.TenantId==tenant&&t.Id==v.TemplateId);if(r.Reason.Length>2000)throw new DomainException("Reason exceeds 2,000 characters");if(r.PreviousId!=null){var previous=await db.Set<Credential>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==r.PreviousId&&c.MembershipId==m.Id&&c.Kind==template.Kind)??throw new AccessDeniedException();if(r.Reason.Length<3)throw new DomainException("Explain renewal, correction or replacement");}
  if(r.PreviousId==null&&template.Kind=="Card"&&await db.Set<Credential>().AnyAsync(c=>c.TenantId==tenant&&c.MembershipId==m.Id&&c.Kind=="Card"&&c.Category==template.Category&&new[]{"Pending Approval","Approved","Generated","Issued"}.Contains(c.Status)&&c.ExpiryDate>=FinanceService.Today))throw new DomainException("A current card exists; use the explicit replacement/renewal workflow");
  var token=CommunityService.Token();var card=new Credential{TenantId=tenant,UnitId=m.ChapterId,MembershipId=m.Id,PersonId=m.PersonId,TemplateVersionId=v.Id,JobId=job,PreviousId=r.PreviousId,Kind=template.Kind,Category=template.Category,Serial=(template.Kind=="Card"?"ID":"CERT")+"-"+DateTime.UtcNow.Year+"-"+Guid.NewGuid().ToString("N")[..16].ToUpperInvariant(),Status=approver==null?"Pending Approval":"Approved",AuthorId=access.UserId,ApproverId=approver,IssueDate=FinanceService.Today,ExpiryDate=r.ExpiryDate,TokenHash=CommunityService.Hash(token),ProtectedToken=protection.CreateProtector("assemblia.credential.token.v1").Protect(token),Reason=r.Reason,EventId=r.EventId,ProjectId=r.ProjectId};card.Snapshot=JsonSerializer.Serialize(await Snapshot(tenant,m,v,card.IssueDate,card.ExpiryDate,card.Serial,token,r.Reason,r.EventId,r.ProjectId),DesignSchema.Json);db.Add(card);access.Audit(tenant,"credential.requested",card.Id,new{card.Kind,card.MembershipId,card.TemplateVersionId});return card;
 }
 public async Task<Credential> Read(Guid tenant,Guid id){await access.Member(tenant);var c=await db.Set<Credential>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();if(!await Own(tenant,c.MembershipId))await Require(tenant,"studio.read",c.UnitId);return c;}
 public async Task Download(Credential card){if(await Own(card.TenantId,card.MembershipId)){if(!(await Policy(card.TenantId)).MemberDownloads)throw new AccessDeniedException();}else await Require(card.TenantId,"studio.read",card.UnitId);if(card.PdfId==null||card.Status is not("Issued" or "Expired" or "Replaced" or "Revoked"))throw new DomainException("Official files are available only after generation and issue");}
 public void Decision(Guid tenant,Guid resource,Guid? unit,string kind,StudioReview r){if(r.Decision is not("Approve" or "Reject")||r.Note.Length>2000)throw new DomainException("Choose Approve or Reject");db.Add(new CommunityDecision{TenantId=tenant,ResourceId=resource,ActorId=access.UserId,UnitId=unit,Kind=kind,Decision=r.Decision,Note=r.Note,Permission=kind.StartsWith("Service")?"service.approve":"studio.approve"});access.Audit(tenant,kind+".reviewed",resource,new{r.Decision});}
}
